package uz.hamkorbank.commhub.application.port.out.provider;

import java.util.Optional;
import uz.hamkorbank.commhub.domain.model.Timing;
import uz.hamkorbank.commhub.domain.model.content.SmsContent;
import uz.hamkorbank.commhub.domain.model.vo.MessageId;
import uz.hamkorbank.commhub.domain.model.vo.Msisdn;
import uz.hamkorbank.commhub.domain.model.vo.ProviderMessageId;
import uz.hamkorbank.commhub.domain.model.vo.ProviderRef;
import uz.hamkorbank.commhub.domain.support.Guard;

/**
 * One SMS handed to a provider adapter (PM-01, SG-01).
 *
 * @param providerMessageId id generated by the Hub for providers that require one (Playmobile, ≤ 20
 *     characters, §9.1); {@code null} when the provider assigns it in its response (SMS Gate)
 * @param timing send window and TTL, forwarded to providers supporting it and enforced by the Hub
 *     scheduler otherwise (§9.1, SG-01)
 * @param templateBinding provider-side template to use instead of the text (FR-4.5); may be null
 */
public record SmsSubmission(
        ProviderRef provider,
        MessageId messageId,
        ProviderMessageId providerMessageId,
        Msisdn recipient,
        SmsContent content,
        Timing timing,
        ProviderTemplateBinding templateBinding,
        SubmissionContext context) {

    public SmsSubmission {
        Guard.notNull(provider, "SmsSubmission.provider");
        Guard.notNull(messageId, "SmsSubmission.messageId");
        Guard.notNull(recipient, "SmsSubmission.recipient");
        Guard.notNull(content, "SmsSubmission.content");
        Guard.notNull(timing, "SmsSubmission.timing");
        Guard.notNull(context, "SmsSubmission.context");
    }

    public Optional<ProviderMessageId> providerMessageIdOptional() {
        return Optional.ofNullable(providerMessageId);
    }

    public Optional<ProviderTemplateBinding> templateBindingOptional() {
        return Optional.ofNullable(templateBinding);
    }
}
